// One-bit Moore state machine. Transitions are registered; outputs are
// combinationaly dependent on the current state.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    // State encoding: 00=walk left, 01=walk right, 10=fall, 11=dig
    reg [1:0] state, next_state;
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else state <= next_state;
    end
    always @(*) begin
        case (state)
            2'b00: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
            2'b01: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 0; end
            2'b10: begin walk_left = 0; walk_right = 0; aaah = 1; digging = 0; end
            2'b11: begin walk_left = 0; walk_right = 0; aaah = 0; digging = 1; end
        endcase
    end
    always @(*) begin
        case (state)
            2'b00: next_state = bump_left ? 2'b01 : (bump_right ? 2'b10 : (ground ? 2'b00 : (dig ? 2'b11 : 2'b00)));
            2'b01: next_state = bump_left ? 2'b10 : (bump_right ? 2'b00 : (ground ? 2'b01 : (dig ? 2'b11 : 2'b01)));
            2'b10: next_state = ground ? (bump_left ? 2'b01 : 2'b00) : (bump_left ? 2'b10 : (bump_right ? 2'b00 : 2'b10));
            2'b11: next_state = ground ? (bump_left ? 2'b01 : (bump_right ? 2'b00 : 2'b11)) : (bump_left ? 2'b10 : (bump_right ? 2'b00 : 2'b11));
        endcase
    end
endmodule

// Moore state machine, one-hot encoded state transitions
module TopModule(input clk, input areset, input bump_left, input bump_right, input ground, input dig, output reg walk_left, output reg walk_right, output reg aaah, output reg digging);
    reg [2:0] state, next_state;
    always @(*) begin
        case (state)
            3'b000: next_state = ground ? (bump_left ? 3'b001 : (bump_right ? 3'b010 : 3'b000)) : 3'b100;
            3'b001: next_state = ground ? (bump_right ? 3'b000 : (bump_left ? 3'b001 : (dig ? 3'b101 : 3'b001))) : 3'b100;
            3'b010: next_state = ground ? (bump_left ? 3'b010 : (bump_right ? 3'b000 : (dig ? 3'b101 : 3'b010))) : 3'b100;
            3'b100: next_state = ground ? (bump_left ? 3'b001 : (bump_right ? 3'b010 : 3'b100)) : 3'b100;
            3'b101: next_state = ground ? 3'b000 : (bump_left ? 3'b001 : (bump_right ? 3'b010 : 3'b101));
            default: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= 3'b000;
        else state <= next_state;
    end
    always @(*) begin
        walk_left = (state == 3'b000) | (state == 3'b101);
        walk_right = (state == 3'b001) | (state == 3'b101);
        aaah = (state == 3'b100);
        digging = (state == 3'b101);
