// Moore state machine: outputs depend only on the current state and the
// inputs.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    // Define the states. Name them s0, s1, ..., sn.
    localparam S_LEFT = 1'b0;
    localparam S_RIGHT = 1'b1;
    // Register and wire the current state and the inputs.
    reg state;
    wire bumped = bump_left | bump_right;
    wire falling = !ground;
    wire walking = ground & !falling;
    always @(posedge clk) begin
        if (areset) state <= S_LEFT;
        else begin
            case (state)
                S_LEFT: begin
                    if (bumped) state <= S_RIGHT;
                    else if (falling) state <= S_LEFT;
                    else if (dig) state <= S_LEFT;
                end
                S_RIGHT: begin
                    if (bumped) state <= S_LEFT;
                    else if (falling) state <= S_RIGHT;
                    else if (dig) state <= S_RIGHT;
                end
            endcase
        end
    end
    // Compute the outputs from the current state and the inputs.
    always @(*) begin
        walk_left = (state == S_LEFT);
        walk_right = (state == S_RIGHT);
        aaah = falling;
        digging = dig & walking;
    end
endmodule

