  wire walk, fall, digg;
  assign walk = (state == 2'b00) || (state == 2'b01);
  assign fall = (state == 2'b10);
  assign digg = (state == 2'b11) && ground;
  assign walk_left = walk & ~fall;
  assign walk_right = walk & fall;
  assign aaah = fall;
  assign digging = digg;
  always @(*) begin
    case (state)
      2'b00: nextstate = bump_left ? 2'b01 : 2'b00;
      2'b01: nextstate = bump_left ? 2'b00 : (bump_right ? 2'b10 : 2'b01);
      2'b10: nextstate = ground ? (bump_left ? 2'b01 : 2'b00) : (dig ? 2'b11 : 2'b10);
      2'b11: nextstate = ground ? (bump_left ? 2'b01 : (bump_right ? 2'b00 : 2'b10)) : (dig ? 2'b11 : 2'b10);
    endcase
  end
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else state <= nextstate;
  end
endmodule

