// Moore state machine, one register per state and combinational
// next-state logic. Same function as the same-named inline FSM in the
// reference, so the two should be functionally equivalent.
module TopModule(input clk, input areset, input bump_left, input bump_right, input ground, input dig, output reg walk_left, output reg walk_right, output reg aaah, output reg digging);
    reg [2:0] state, nextstate;
    always @(posedge clk) begin
        if (areset) state <= 3;
        else state <= nextstate;
    end
    always @(*) begin
        case (state)
            3: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
            0: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
            1: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 0; end
            2: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 0; end
            4: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 1; end
            5: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 1; end
            6: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 1; end
            7: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
            8: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
            default: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; end
        endcase
    end
    always @(*) begin
        case (state)
            3: nextstate = bump_left ? 1 : (bump_right ? 0 : 3);
            0: nextstate = bump_left ? 2 : (bump_right ? 4 : (ground ? 8 : (dig ? 5 : 0)));
            1: nextstate = bump_right ? 0 : (bump_left ? 4 : (ground ? 7 : (dig ? 6 : 1)));
            2: nextstate = bump_right ? 1 : (bump_left ? 5 : (ground ? 8 : (dig ? 6 : 2)));
            4: nextstate = bump_right ? 2 : (bump_left ? 0 : (ground ? 7 : (dig ? 5 : 4)));
            5: nextstate = bump_left ? 4 : (bump_right ? 1 : (ground ? 8 : (dig ? 6 : 5)));
            6: nextstate = bump_left ? 5 : (bump_right ? 2 : (ground ? 7 : (dig ? 0 : 6)));
            7: nextstate = bump_right ? 4 : (bump_left ? 1 : (ground ? 8 : (dig ? 5 : 7)));
            8: nextstate = bump_right ? 0 : (bump_left ? 2 : 8);
            default: nextstate = 3;
        endcase
    end
    always @(*) aaah = (state == 0 && !ground) || (state == 2 && !ground) || (state == 4 && !ground) || (state == 6 && !ground);
endmodule

